#include "ProjectVersions.h"
static void testProjectVersions(const File& root,Assets& assets){
    auto folder=root.getChildFile("version-core-"+Uuid().toString()),library=folder.getChildFile("Versions");folder.createDirectory();String message;auto rows=scanProjectVersions(library,{},message);expect(rows.empty()&&!library.exists(),"missing version library lists empty without creating folders");
    auto sample=folder.getChildFile("source.wav");AudioBuffer<float> audio(2,4800);for(int i=0;i<4800;++i){audio.setSample(0,i,.25f);audio.setSample(1,i,-.125f);}auto stream=sample.createOutputStream();WavAudioFormat wav;std::unique_ptr<AudioFormatWriter> writer(stream?wav.createWriterFor(stream.get(),48000,2,24,{},0):nullptr);expect(writer!=nullptr,"create version audio fixture");if(!writer)return;stream.release();expect(writer->writeFromAudioSampleBuffer(audio,0,4800),"write version audio fixture");writer.reset();auto audioHash=SHA256(sample).toHexString();
    auto p=emptyProject();p.title="Version test";p.loop=false;p.tracks[7].instrument=Instrument::sample;p.tracks[7].samplePath="source.wav";p.tracks[7].sampleStart=.01;p.tracks[7].sampleEnd=.08;p.tracks[7].sampleLoop=true;p.patterns[0].lanes[7]={{0,.2,60,.7f,.8f,2}};p.patterns[0].colour=5;p.markers={{"section","Verse",0,4,2}};p.notes="Original song notes";auto before=JSON::toString(projectToJson(p));File first,second;
    expect(saveProjectVersion(p,folder,library,"First mix",first).wasOk()&&first.existsAsFile()&&first.getFileName().contains("First mix"),"named project snapshot publishes a standard native project");expect(saveProjectVersion(p,folder,library,"First mix",second).wasOk()&&first!=second&&first.existsAsFile(),"rapid snapshots with identical labels never overwrite each other");expect(JSON::toString(projectToJson(p))==before&&SHA256(sample).toHexString()==audioHash,"version save preserves source song and sample bytes");rows=scanProjectVersions(library,"FIRST mix",message);expect(rows.size()==2&&message.contains("Newest first"),"version search matches all words case-insensitively");expect(rows[0].modified>=rows[1].modified,"version browser sorts newest snapshots first");
    Project restored;String token;auto row=*std::find_if(rows.begin(),rows.end(),[&](const ProjectVersion& v){return v.file==first;});expect(readProjectVersion(row,restored,token).wasOk()&&token==projectVersionToken(first),"version inspection captures a stable content token");expect(File::isAbsolutePath(restored.tracks[7].samplePath)&&File(restored.tracks[7].samplePath).isAChildOf(library)&&SHA256(File(restored.tracks[7].samplePath)).toHexString()==audioHash,"version uses its collected audio independently of original sample paths");expect(restored.patterns[0].lanes[7]==p.patterns[0].lanes[7]&&restored.patterns[0].colour==5&&restored.tracks[7].sampleStart==.01&&restored.tracks[7].sampleEnd==.08&&restored.tracks[7].sampleLoop,"snapshot preserves articulation colour sampler selection and looping");auto same=compareProjectVersion(restored,library,restored,library);expect(same.contains("data: identical")&&same.contains("0 channel/pattern lanes changed"),"identical versions compare structurally equal");
    auto edited=restored;edited.bpm=90;edited.tracks[7].volume=.2f;edited.patterns[0].lanes[7].push_back({2,.5,64,.8f});edited.markers[0].name="Refrain";edited.notes="Changed notes";edited.clips.push_back({7,0,0,8});auto diff=compareProjectVersion(restored,library,edited,library);expect(diff.contains("118.000 -> 90.000 BPM")&&diff.contains("Notes: 1 -> 2")&&diff.contains("1 channel settings changed")&&diff.contains("1 channel/pattern lanes changed"),"version comparison identifies tempo channel and note-lane changes");expect(diff.contains("Arrangement: changed; markers: changed; project notes: changed")&&diff.contains("data: differs"),"version comparison includes Playlist markers project notes and complete data");
    auto fewer=emptyProject();fewer.tracks.resize(1);for(auto& pat:fewer.patterns)pat.lanes.resize(1);auto countDiff=compareProjectVersion(fewer,folder,p,folder);expect(countDiff.contains("Channels: 1 -> 8")&&countDiff.contains("Patterns: 1 -> 1"),"comparison handles added and removed channel lanes without out-of-range access");auto abs=absoluteAssets(p,folder);expect(compareProjectVersion(p,folder,abs,folder).contains("data: identical"),"relative and absolute references to the same source compare equally");
    auto old=JSON::toString(projectToJson(restored));String oldToken=token;auto text=first.loadFileAsString();first.replaceWithText(text+"\n");expect(readProjectVersion(row,restored,token).failed()&&JSON::toString(projectToJson(restored))==old&&token==oldToken,"changed snapshot metadata rejects without replacing caller project or token");first.replaceWithText(text);
    auto sentinel=folder.getChildFile("sentinel.pulse");File output=sentinel;std::atomic<bool> cancel{true};expect(saveProjectVersion(p,folder,library,"Cancelled",output,&cancel).failed()&&output==sentinel,"cancelled version save retains caller output and original snapshots");expect(scanProjectVersions(library,{},message,&cancel).empty()&&message.contains("cancelled"),"cancelled version scan does not publish a partial listing");
    for(auto label:{"bad/name","bad:name"," leading","trailing ","bad\nlabel"})expect(saveProjectVersion(p,folder,library,label,output).failed()&&output==sentinel,"invalid snapshot label rejects before publishing data");expect(saveProjectVersion(p,folder,library,String::repeatedString("x",65),output).failed()&&output==sentinel,"snapshot label length is bounded");auto missing=p;missing.tracks[7].samplePath="missing.wav";expect(saveProjectVersion(missing,folder,library,"Missing",output).failed()&&output==sentinel&&first.existsAsFile()&&second.existsAsFile(),"missing source blocks a new version without damaging previous snapshots");auto invalid=p;invalid.patterns[0].lanes.clear();expect(saveProjectVersion(invalid,folder,library,"Invalid",output).failed()&&output==sentinel,"malformed musical data cannot publish a version");
    auto blocked=folder.getChildFile("blocker");blocked.replaceWithText("keep");expect(saveProjectVersion(p,folder,blocked,"Blocked",output).failed()&&blocked.loadFileAsString()=="keep","snapshot write failure retains existing filesystem data");
    auto corrupt=library.getChildFile("Corrupt version.pulse");corrupt.replaceWithText("broken JSON");rows=scanProjectVersions(library,"Corrupt",message);expect(rows.size()==1,"version list can expose a damaged snapshot for a clear inspection error");if(!rows.empty())expect(readProjectVersion(rows.front(),restored,token).failed()&&JSON::toString(projectToJson(restored))==old,"corrupt snapshot inspection retains current caller data");
    auto unrelated=library.getChildFile("Unrelated.txt");unrelated.replaceWithText("keep");auto nested=library.getChildFile("Nested");nested.createDirectory();saveProject(p,nested.getChildFile("nested.pulse"));expect(scanProjectVersions(library,"nested",message).empty(),"version scan stays in the chosen folder and ignores nested projects and non-project files");
    auto capacity=folder.getChildFile("Capacity");capacity.createDirectory();auto now=Time::getCurrentTime();for(int i=0;i<270;++i){auto file=capacity.getChildFile("Capacity row "+String(i).paddedLeft('0',3)+".pulse");file.replaceWithText("{}");file.setLastModificationTime(Time(now.toMilliseconds()+i*1000));}rows=scanProjectVersions(capacity,"Capacity row",message);expect(rows.size()==maxVersionRows&&rows.front().file.getFileName().contains("269")&&message.contains("limit"),"large version lists retain the newest 256 matching rows with an explicit limit");expect(scanProjectVersions(capacity,String::repeatedString("x",161),message).empty()&&message.contains("160"),"version search length is bounded");
    auto originalAudio=render(p,assets,folder,24000);sample.deleteFile();Assets independent;auto restoredAudio=render(restored,independent,library,24000,127);bool equal=true;for(int c=0;c<2;++c)for(int i=0;i<24000;++i)equal&=originalAudio.getSample(c,i)==restoredAudio.getSample(c,i);expect(equal&&restoredAudio.getMagnitude(0,0,24000)>.001f,"version audio renders sample-exactly after the original source is removed");
}
